effect.shader:
// k ÷ 255 com o arredondamento certo: o float EXATO que a textura de 8 bits devolve ao AM (ver `am-color-balance.xml`).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;                                                    // o bit mais alto de n
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;                      // entre 2^23 e 2^24
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

// A cor reta do Nova pré-multiplicada EM 8 BITS, pelo mais perto (o premul do Android): o que a textura do AM guarda.
// No opaco a cor já é o float da textura, bit a bit.
vec4 doAm(vec4 c) {
    if (c.a >= 1.0) return c;
    vec3 k = floor(c.rgb * c.a * 255.0 + 0.5);
    return vec4(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b), c.a);
}

void main() {
    if (acPass == 1) {
        // A pré-multiplicada do AM, já em 8 bits, de volta para a cor reta do Nova.
        vec4 q = texture(copia, acScreenNorm);
        fragColor = q.a > 0.0 ? vec4(clamp(q.rgb / q.a, 0.0, 1.0), q.a) : vec4(0.0);
        return;
    }
    // O fundo no pixel da tela (na tela, o `acTela` é a identidade).
    ivec2 T = textureSize(comp, 0);
    ivec2 px = clamp(ivec2(floor(acTela(acScreenNorm) * vec2(T))), ivec2(0), T - 1);
    vec4 fundo = doAm(texelFetch(comp, px, 0));

    // O shader do AM: `mix(comp × texColor.a, texColor, fill)`, na pré-multiplicada.
    vec4 texColor = doAm(texture(inputImg, acScreenNorm));
    // O corte em 0..1 é o do alvo de 8 bits do AM; escrito aqui para o projeto de 32 bits sair igual.
    fragColor = clamp(mix(fundo * texColor.a, texColor, fill), 0.0, 1.0);
}
